import { Component, OnInit, ChangeDetectionStrategy, Input, ViewChild } from '@angular/core';
import { DestroySubject } from '@honoregaming/core';
import { Media, MediaService, MessageService } from '@honoregaming/ui';
import { takeUntil } from 'rxjs/operators';
import { CharityBasketPopupComponent } from '../charity-basket-popup/charity-basket-popup.component';
import { Charity } from '../../models/charity.model';

@Component({
  selector: 'hg-charity-basket',
  templateUrl: './charity-basket.component.html',
  styleUrls: ['./charity-basket.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class CharityBasketComponent extends DestroySubject implements OnInit {
  media: Media;
  showPopup: boolean = false;

  @Input()
  charity: Charity;

  @ViewChild(CharityBasketPopupComponent)
  basketInstance: CharityBasketPopupComponent;

  constructor(private readonly mediaService: MediaService, private readonly messageService: MessageService) {
    super();
  }

  ngOnInit(): void {
    this.mediaService.media$.pipe(takeUntil(this.destroy$)).subscribe(media => {
      this.media = media;
    });
  }

  openBasket(event: Event) {
    event.stopPropagation();
    event.preventDefault();

    if (this.media <= Media.sm) {
      this.showPopup = true;
    } else {
      this.messageService.sendComponentMessage(
        CharityBasketPopupComponent,
        { charity: this.charity },
        {
          canBeDismissed: true,
          displayClose: true,
          zIndex: 14
        }
      );
    }
  }

  closeBasket() {
    if (this.basketInstance) {
      this.basketInstance.hasDonated = false;
      this.basketInstance.cdRef.markForCheck();
    }
    this.showPopup = false;
  }

  preventClick(event: Event) {
    this.closeBasket();
    event.preventDefault();
    event.stopPropagation();
  }
}
