import {
  Component,
  OnInit,
  ChangeDetectionStrategy,
  Output,
  EventEmitter,
  Input,
  Inject,
  ChangeDetectorRef
} from '@angular/core';
import { BetSlipService } from '@honoregaming/betslip';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { DestroySubject, DialogService } from '@honoregaming/core';
import { AuthService, Me } from '@honoregaming/customer-core';
import { BalanceNotEnoughComponent } from '@honoregaming/customer-ui';
import { Media, MediaService, MessageService } from '@honoregaming/ui';
import { finalize, takeUntil } from 'rxjs/operators';
import { CharityService } from '../../services/charity.service';
import { Charity } from '../../models/charity.model';
import { CharityDonationFailure } from '../../models/charity-donation-failure.model';

@Component({
  selector: 'hg-charity-basket-popup',
  templateUrl: './charity-basket-popup.component.html',
  styleUrls: ['./charity-basket-popup.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class CharityBasketPopupComponent extends DestroySubject implements OnInit {
  presets: number[];
  donation: number;
  me: Me;
  userStatus: 'connected' | 'disconnected';
  userNeedToBeLoggedIn: boolean = false;
  error: boolean = false;
  media: Media;
  currency: string;
  hasDonated: boolean = false;
  freebetReceived: number = 0;
  loading: boolean = false;

  @Output()
  close = new EventEmitter();

  @Input()
  charity: Charity;

  identityNotValidated = false;

  constructor(
    private readonly dialogService: DialogService,
    private readonly authService: AuthService,
    private readonly mediaService: MediaService,
    @Inject(operatorConfigurationToken) private readonly operatorConfiguration: OperatorConfiguration,
    public readonly cdRef: ChangeDetectorRef,
    private readonly betSlipService: BetSlipService,
    private readonly messageService: MessageService,
    private readonly charityService: CharityService
  ) {
    super();
  }

  ngOnInit(): void {
    this.authService.me$
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.cdRef.markForCheck();
        })
      )
      .subscribe(me => {
        this.me = me;
        this.charityService.getCharitiesAmounts();
      });

    this.currency = this.operatorConfiguration.currency.symbol;

    this.authService.status$.pipe(takeUntil(this.destroy$)).subscribe(status => {
      this.userStatus = status;
      if (this.userStatus === 'connected') {
        this.userNeedToBeLoggedIn = false;
        this.cdRef.markForCheck();
      }
    });

    this.betSlipService.$configuration.pipe(takeUntil(this.destroy$)).subscribe(conf => {
      this.presets = conf.predefinedStakes ?? [50, 100, 200, 500];
    });

    this.mediaService.media$.pipe(takeUntil(this.destroy$)).subscribe(media => {
      this.media = media;
    });
  }

  setDonation(value: number) {
    this.donation = value;
  }

  donate() {
    if (this.loading) {
      return;
    }

    if (this.userStatus === 'disconnected') {
      this.userNeedToBeLoggedIn = true;
      this.cdRef.markForCheck();

      if (this.media <= Media.sm) {
        this.dialogService.toggleDialog('login', true);
      }
    } else if (this.me.balance < this.donation) {
      this.messageService.sendComponentMessage(BalanceNotEnoughComponent, {
        titleTranslation: 'CHARITY.BALANCE_NOT_ENOUGH.TITLE',
        bodyTranslation: 'CHARITY.BALANCE_NOT_ENOUGH',
        isFreeBet: false
      });
    } else if (this.donation > 0) {
      this.loading = true;
      this.error = this.identityNotValidated = false;
      this.charityService
        .donateToCharity(this.charity.id, this.donation)
        .pipe(
          takeUntil(this.destroy$),
          finalize(() => {
            this.cdRef.markForCheck();
          })
        )
        .subscribe(
          result => {
            this.loading = false;
            if (result?.success) {
              this.hasDonated = true;
              this.freebetReceived = result.freebetReceived;
              this.charityService.getCharitiesAmounts();
            } else {
              this.error = true;
            }
          },
          err => {
            this.loading = false;
            if (err.error.code === CharityDonationFailure.InsufficientFunds) {
              this.messageService.sendComponentMessage(BalanceNotEnoughComponent, {
                titleTranslation: 'CHARITY.BALANCE_NOT_ENOUGH.TITLE',
                bodyTranslation: 'CHARITY.BALANCE_NOT_ENOUGH',
                isFreeBet: false
              });
            } else if (err.error.code === CharityDonationFailure.CustomerIdentityNotValidated) {
              this.identityNotValidated = true;
            } else {
              this.error = true;
            }
          }
        );
    }
  }

  onClose() {
    this.close.emit();
  }

  preventClick(event: Event) {
    event.preventDefault();
    event.stopPropagation();
  }
}
