import { Component, OnInit, ChangeDetectionStrategy, Input } from '@angular/core';
import { I18nService } from '@honoregaming/i18n';
import { interval, Observable } from 'rxjs';
import { map } from 'rxjs/operators';

@Component({
  selector: 'hg-countdown',
  templateUrl: './countdown.component.html',
  styleUrls: ['./countdown.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class CountdownComponent implements OnInit {
  @Input()
  date: string;

  dateInstance: Date;

  text$: Observable<string>;

  dateText: string;

  countdown$: Observable<string>;

  constructor(private readonly i18nService: I18nService) {}

  ngOnInit(): void {
    if (this.date) {
      this.dateInstance = new Date(this.date);

      if (this.dateInstance < new Date().addDays(2)) {
        this.countdown$ = interval(1000).pipe(map(_ => this.processCountDown()));

        if (this.dateInstance < new Date().addDays(1)) {
          this.text$ = this.i18nService.translate('CHARITY.ONLY_LEFT');
        } else {
          this.text$ = this.i18nService.translate('CHARITY.ENDS_IN');
        }
      } else if (this.dateInstance < new Date().addDays(7)) {
        this.text$ = this.i18nService.translate('CHARITY.FINISHES_IN');

        this.i18nService.translate('CHARITY.DAYS').subscribe(message => {
          const dateDiff = Math.abs(this.dateInstance.getTime() - new Date().getTime());
          const dayDiff = Math.floor(dateDiff / (1000 * 60 * 60 * 24));
          this.dateText = `${dayDiff} ${message}`;
        });
      } else {
        this.dateText = this.dateInstance.toLocaleDateString();
        this.text$ = this.i18nService.translate('CHARITY.ENDED_ON');
      }
    }
  }

  processCountDown(): string {
    let remaining = (this.dateInstance.getTime() - new Date().getTime()) / 1000;

    const countDownSecs = Math.floor(remaining % 60);
    remaining = Math.floor(remaining / 60);

    const countDownMins = Math.floor(remaining % 60);
    remaining = Math.floor(remaining / 60);

    const countDownHours = remaining;

    return `${countDownHours} : ${countDownMins.toString().padStart(2, '0')} : ${countDownSecs
      .toString()
      .padStart(2, '0')}`;
  }
}
