import { Component, ChangeDetectorRef, OnInit } from '@angular/core';
import { DestroySubject } from '@honoregaming/core';
import { AuthService, CustomerSuperReferrerState, Me } from '@honoregaming/customer-core';
import { finalize, takeUntil } from 'rxjs/operators';
import { SuperReferrerRegistrationFailure } from '../../models/super-referrer-registration-failure.enum';
import { SuperReferrerService } from '../../services/super-referrer.service';

const MESSAGE_ERROR = 'COMMON.GENERIC_ERROR';

@Component({
  selector: 'hg-super-referrer',
  templateUrl: './super-referrer.component.html',
  styleUrls: ['./super-referrer.component.scss']
})
export class SuperReferrerComponent extends DestroySubject implements OnInit {
  me: Me;
  email: string;
  loading = false;
  error = false;
  success = false;
  messageError = MESSAGE_ERROR;
  CustomerSuperReferrerState = CustomerSuperReferrerState;

  constructor(
    private superReferrerService: SuperReferrerService,
    private cdRef: ChangeDetectorRef,
    private authService: AuthService
  ) {
    super();
  }

  ngOnInit() {
    this.authService.me$.pipe(takeUntil(this.destroy$)).subscribe(me => {
      this.me = me;
      this.cdRef.markForCheck();
    });
  }

  submit() {
    if (!this.email || this.loading || !this.me) {
      return;
    }

    this.loading = true;
    this.error = false;
    this.success = false;
    this.messageError = MESSAGE_ERROR;

    this.superReferrerService
      .superReferrerRegistration(this.email)
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.loading = false;
          this.cdRef.markForCheck();
        })
      )
      .subscribe(
        _ => {
          this.success = true;
          this.email = null;
        },
        err => {
          if (err.status === 401) {
            this.messageError = 'SUPER-REFERRER.NEED_TO_BE_LOGGEDIN';
          }

          if (err.error?.code === SuperReferrerRegistrationFailure.RequestIsAlreadyInProgress) {
            this.messageError = 'SUPER-REFERRER.REQUEST-ALREADY-EXISTS';
          }

          this.error = true;
        }
      );
  }
}
