import {
  OnChanges,
  Directive,
  ElementRef,
  Output,
  EventEmitter,
  Input,
  SimpleChanges,
  OnDestroy,
  PLATFORM_ID,
  Inject,
  NgZone
} from '@angular/core';
import { Point } from '../../models/points-of-sale.model';
import { isPlatformBrowser } from '@angular/common';
declare var require: any;
declare var L: any;
let k: any;

@Directive({
  selector: '[hgMap]'
})
export class MapDirective implements OnChanges, OnDestroy {
  isBrower: boolean;
  map;
  loading = false;
  storeLayer;

  private defaultZoomLevel = 16;
  private markers = [];

  @Input()
  me: { latitude: number; longitude: number };
  @Input()
  points: Point[];
  @Input()
  focus: { latitude: number; longitude: number; zoom?: number } = { latitude: 1, longitude: 1 };
  @Output()
  markerClicked = new EventEmitter<Point>();

  constructor(private elementRef: ElementRef, @Inject(PLATFORM_ID) platformId, private zone: NgZone) {
    this.isBrower = isPlatformBrowser(platformId);
    if (this.isBrower) {
      L = require('leaflet');
      k = require('leaflet-knn');
      this.storeLayer = L.geoJSON(null);
    }
  }

  ngOnChanges(changes: SimpleChanges) {
    if (!this.isBrower) {
      return;
    }

    if (changes['points'] || changes['me']) {
      this.drawMap();
    } else if (changes['focus']) {
      this.map?.setView(L.latLng(this.focus.latitude, this.focus.longitude), this.focus.zoom || this.defaultZoomLevel);
    }
  }

  ngOnDestroy(): void {
    if (!this.isBrower) {
      return;
    }

    this.cleanMarkers();
    this.map.remove();
  }

  public drawMap() {
    if (!this.isBrower) {
      return;
    }

    // draw the map only when the dom is rendered to avoid post ssr issues
    this.zone.runOutsideAngular(() => {
      const refreshSize = () => {
        setTimeout(() => {
          if (this.elementRef.nativeElement.offsetParent === null) {
            refreshSize();
          } else {
            this.map = this.map || L.map(this.elementRef.nativeElement, { zoomControl: false });
            this.map.setView(
              L.latLng(this.focus.latitude, this.focus.longitude),
              this.focus.zoom || this.defaultZoomLevel
            );

            this.map.on('moveend zoomend', (_e: any) => this.getNearestFromSearch(this.map.getCenter()));
            L.tileLayer('https://{s}.tile.osm.org/{z}/{x}/{y}.png').addTo(this.map);

            this.cleanMarkers();
            this.drawMarkers();
            setTimeout(() => this.map.invalidateSize());
          }
        }, 500);
      };
      refreshSize();
    });
  }

  private cleanMarkers() {
    for (const marker of this.markers) {
      marker.clearAllEventListeners();
      this.storeLayer.removeLayer(marker);
    }

    this.markers = [];
  }

  private drawMarkers() {
    const myIcon = L.icon({
      iconUrl: '/assets/maps.svg',
      iconSize: [32, 50]
    });

    for (const point of this.points) {
      const marker = L.marker([point.latitude, point.longitude], { icon: myIcon });
      marker
        .addEventListener('click', (e: any) => this.markerClicked.next(this.getPointFromLatLng(e.latlng, this.points)))
        .addTo(this.map)
        .openPopup();

      this.markers.push(marker);
      this.storeLayer.addData(marker.toGeoJSON());
    }

    if (this.me) {
      const marker = L.marker([this.me.latitude, this.me.longitude], {
        icon: L.icon({
          iconUrl: '/assets/my-position.svg',
          iconSize: [17, 25]
        })
      }).addTo(this.map);
      this.markers.push(marker);
    }
  }

  private getNearestFromSearch(point) {
    const nearGJSon = k(this.storeLayer).nearest(point, 1, 10000);
    const near = nearGJSon[0];
    if (near) {
      this.markerClicked.next(this.getPointFromLatLng(L.latLng(near.lat + 0, near.lon + 0), this.points));
    }
  }

  private getPointFromLatLng(latlng, points: Point[]): Point {
    return points.find(x => {
      return x.latitude.toFixed(5) === latlng.lat.toFixed(5) && x.longitude.toFixed(5) === latlng.lng.toFixed(5);
    });
  }
}
