import { Inject, Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { PointsOfSale } from '../models/points-of-sale.model';
import { globalConfiguration, OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { Cacheable } from '@honoregaming/core';

@Injectable({ providedIn: 'root' })
export class ResourcesApiService {
  constructor(
    private httpClient: HttpClient,
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration
  ) {}

  @Cacheable()
  getPointsOfSale(): Observable<PointsOfSale> {
    return this.httpClient.get<PointsOfSale>(
      `${globalConfiguration.staticAssetsPath}${this.operatorConfiguration.commercialCode}/points-of-sale.json`
    );
  }
}
