import {
  Component,
  OnInit,
  ChangeDetectionStrategy,
  ViewEncapsulation,
  ChangeDetectorRef,
  PLATFORM_ID,
  Inject
} from '@angular/core';
import { Point, PointsOfSale } from '../../models/points-of-sale.model';
import { ResourcesApiService } from '../../services/resources-api.service';
import { isPlatformBrowser, Location } from '@angular/common';
import { PointsOfSaleMode, operatorConfigurationToken, OperatorConfiguration } from '@honoregaming/configuration';
import { DestroySubject } from '@honoregaming/core';
import { takeUntil } from 'rxjs/operators';
import { ActivatedRoute } from '@angular/router';
import { MessageService, WarningDataComponent } from '@honoregaming/ui';
declare var require: any;
declare var L: any;

@Component({
  selector: 'hg-points-of-sale',
  templateUrl: './points-of-sale.component.html',
  styleUrls: ['./points-of-sale.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None
})
export class PointsOfSaleComponent extends DestroySubject implements OnInit {
  isBrowser: boolean;
  operatorName: string;

  focus: { latitude: number; longitude: number; zoom?: number };
  pointToDisplay: Point;
  pointsOfSale: PointsOfSale;
  myPosition: { latitude: number; longitude: number };
  category: number = 0;
  pointsForCategory: Point[] = [];

  enableMap = this.operatorConfiguration.features.pointsOfSaleMode === PointsOfSaleMode.WithMap;
  warnOnDataConsumption = this.operatorConfiguration.onlineConfiguration?.warnOnDataConsumption;

  constructor(
    private service: ResourcesApiService,
    private cdRef: ChangeDetectorRef,
    private messageService: MessageService,
    private activeRoute: ActivatedRoute,
    private location: Location,
    @Inject(PLATFORM_ID) platformId,
    @Inject(operatorConfigurationToken) private operatorConfiguration: OperatorConfiguration
  ) {
    super();

    this.isBrowser = isPlatformBrowser(platformId);
    if (this.isBrowser && this.enableMap) {
      L = require('leaflet');
    }
  }

  ngOnInit() {
    this.operatorName = this.operatorConfiguration.resourcesConfiguration?.name ?? this.operatorConfiguration.name;

    if (this.warnOnDataConsumption) {
      this.messageService
        .sendComponentMessage(
          WarningDataComponent,
          {
            messageKey: 'WARN.DATA.POINTOFSALES'
          },
          { queue: true },
          this.destroy$,
          true
        )
        .closed.subscribe(result => {
          if (!result) {
            this.location.back();
            return;
          }
          this.init();
        });
    } else {
      this.init();
    }
  }

  init() {
    this.activeRoute.queryParams.subscribe(p => {
      this.category = p && p['cat'] ? Number(p['cat']) : 0;

      if (
        this.category !== 0 &&
        this.operatorConfiguration.resourcesConfiguration.pointOfSalesCategories.findIndex(x => x == this.category) ===
          -1
      ) {
        this.category = 0;
      }

      if (!this.pointsOfSale) {
        this.load();
      } else {
        this.focus = {
          latitude: this.pointsOfSale.defaultLatitude,
          longitude: this.pointsOfSale.defaultLongitude,
          zoom: this.pointsOfSale.zoom
        };

        this.pointsForCategory = this.pointsOfSale.points.filter(p => p.category === this.category);
        this.cdRef.markForCheck();
      }
    });
  }

  load() {
    this.service
      .getPointsOfSale()
      .pipe(takeUntil(this.destroy$))
      .subscribe(pointsOfSale => {
        this.pointsOfSale = pointsOfSale;

        this.focus = {
          latitude: this.pointsOfSale.defaultLatitude,
          longitude: this.pointsOfSale.defaultLongitude,
          zoom: this.pointsOfSale.zoom
        };

        this.pointsForCategory = this.pointsOfSale.points.filter(p => p.category === this.category);

        if (this.isBrowser && navigator.geolocation && this.enableMap) {
          navigator.geolocation.getCurrentPosition(position => {
            this.myPosition = {
              latitude: position.coords.latitude,
              longitude: position.coords.longitude
            };

            const me = L.latLng(position.coords.latitude, position.coords.longitude);
            this.pointsOfSale.points.forEach(p => {
              p.distance = me.distanceTo(L.latLng(p.latitude, p.longitude));
            });

            this.cdRef.markForCheck();
          });
        }

        this.cdRef.markForCheck();
      });
  }

  onMarkerClicked(point: Point) {
    this.pointToDisplay = point;
  }

  onPointFocus(point: Point) {
    this.pointToDisplay = point;
    this.focus = {
      latitude: point.latitude,
      longitude: point.longitude
    };
  }
}
