import { Component, OnInit, ChangeDetectionStrategy, ChangeDetectorRef } from '@angular/core';
import { Async, AsyncTrigger, DestroySubject } from '@honoregaming/core';
import { I18nService } from '@honoregaming/i18n';
import { ContentService } from '@honoregaming/templating';
import { Content } from '@honoregaming/types';
import { takeUntil } from 'rxjs/operators';

@Component({
  selector: 'hg-faq',
  templateUrl: './faq.component.html',
  styleUrls: ['./faq.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class FaqComponent extends DestroySubject implements OnInit {
  contents: Content[] = [];
  active: number;

  @AsyncTrigger()
  languageTrigger = this.i18nService.languageChanged$;
  constructor(
    private contentService: ContentService,
    private cdRef: ChangeDetectorRef,
    private i18nService: I18nService
  ) {
    super();
  }

  ngOnInit() {
    this.loadContent();
  }

  @Async()
  loadContent() {
    this.contentService
      .getFaqContents()
      .pipe(takeUntil(this.destroy$))
      .subscribe(contents => {
        this.contents = contents;
        this.cdRef.markForCheck();
      });
  }

  scrollToFaqContent(index) {
    setTimeout(() => {
      var faqContent = document.getElementById(index);

      const rect = faqContent.getBoundingClientRect();
      var isVisibleInViewport =
        rect.top >= 0 &&
        rect.left >= 0 &&
        rect.bottom <= (window.innerHeight || document.documentElement.clientHeight) &&
        rect.right <= (window.innerWidth || document.documentElement.clientWidth);

      if (!isVisibleInViewport) faqContent.scrollIntoView();
    });
  }
}
