import { Component, OnInit, ChangeDetectionStrategy, ChangeDetectorRef, Inject, ViewChild } from '@angular/core';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { CharityService } from '../../services/charity.service';
import { Async, AsyncTrigger, DestroySubject } from '@honoregaming/core';
import { filter, finalize, switchMap, takeUntil } from 'rxjs/operators';
import { Charity } from '../../models/charity.model';
import { ActivatedRoute } from '@angular/router';
import { I18nService } from '@honoregaming/i18n';
import { CharityAmount } from '../../models/charity-amount.model';
import { CharityBasketPopupComponent } from '../../components/charity-basket-popup/charity-basket-popup.component';
import { Media, MediaService, MessageService } from '@honoregaming/ui';
import { CharityDonation } from '../../models/charity-donation.model';
import { AuthService } from '@honoregaming/customer-core';

export interface SocialNetwork {
  link: string;
  className: string;
}

@Component({
  selector: 'hg-charity-page',
  templateUrl: './charity-page.component.html',
  styleUrls: ['./charity-page.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class CharityPageComponent extends DestroySubject implements OnInit {
  charity: Charity;
  currency: string;
  socialNetworks: SocialNetwork[] = [];
  media: Media;
  showBasket: boolean = false;
  showFaq: boolean = true;
  donationsPage: number = 0;
  donationsPageSize: number = 20;
  hasMoreDonations: boolean = true;

  donations: CharityDonation[] = [];

  @ViewChild(CharityBasketPopupComponent)
  basketInstance: CharityBasketPopupComponent;

  @AsyncTrigger()
  languageTrigger = this.i18nService.languageChanged$;

  constructor(
    private readonly charityService: CharityService,
    private readonly cdRef: ChangeDetectorRef,
    @Inject(operatorConfigurationToken) private readonly operatorConfiguration: OperatorConfiguration,
    private readonly route: ActivatedRoute,
    private readonly i18nService: I18nService,
    private readonly mediaService: MediaService,
    private readonly messageService: MessageService,
    private readonly authService: AuthService
  ) {
    super();
  }

  ngOnInit(): void {
    this.currency = this.operatorConfiguration.currency.symbol;

    this.mediaService.media$.pipe(takeUntil(this.destroy$)).subscribe(media => (this.media = media));

    this.loadCharity();

    this.loadDonations();

    this.authService.me$
      .pipe(takeUntil(this.destroy$))
      .subscribe(_ => this.charityService.getCharityAmount(+this.route.snapshot.paramMap.get('charityId')));
  }

  @Async()
  loadCharity() {
    this.charityService
      .getCharity(+this.route.snapshot.paramMap.get('charityId'))
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.cdRef.markForCheck();
        }),
        switchMap(charity => {
          this.socialNetworks = [];
          this.charity = charity;
          this.processSocialLinks();
          this.charityService.getCharityAmount(this.charity.id);

          return this.charityService.charityAmount$;
        }),
        filter(charityAmount => charityAmount !== null)
      )
      .subscribe(charityAmount => {
        this.updateAmount(charityAmount);
      });
  }

  loadDonations() {
    if (this.hasMoreDonations) {
      this.charityService
        .getCharityDonations(+this.route.snapshot.paramMap.get('charityId'), this.donationsPage, this.donationsPageSize)
        .pipe(
          takeUntil(this.destroy$),
          finalize(() => {
            this.cdRef.markForCheck();
          })
        )
        .subscribe(donations => {
          if ((donations?.length ?? 0) < this.donationsPageSize) {
            this.hasMoreDonations = false;
          }

          this.donations.push(...donations);
        });

      this.donationsPage++;
    }
  }

  trackFn(index, _donation: CharityDonation) {
    return index;
  }

  processSocialLinks() {
    if (this.charity.socialNetworks?.length) {
      this.charity.socialNetworks.forEach(socialNetworkLink => {
        const className = this.getSocialNetworkClass(socialNetworkLink);

        if (className) {
          this.socialNetworks.push({
            link: socialNetworkLink,
            className
          });
        }
      });
    }
  }

  updateAmount(charityAmount: CharityAmount) {
    this.charityService.updateCharityAmount(this.charity, charityAmount);
    this.cdRef.markForCheck();
  }

  getSocialNetworkClass(link: string): string {
    const socialLinkRegex = new RegExp(
      /^(?:https?:\/\/)?.*\b(twitter\.com|x\.com|facebook\.com|instagram\.com|t\.me|tiktok\.com|whatsapp\.com|youtube\.com|youtu\.be|snapchat\.com|linkedin\.com|threads\.net|threads\.com|messenger\.com)(?:\/.*)?$/
    );

    const matches = socialLinkRegex.exec(link);

    if (!matches) {
      return 'hg-web';
    }

    switch (matches[1]) {
      case 'x.com':
      case 'twitter.com':
        return 'hg-x';
      case 'facebook.com':
        return 'hg-facebook';
      case 'instagram.com':
        return 'hg-instagram';
      case 't.me':
        return 'hg-telegram';
      case 'tiktok.com':
        return 'hg-tiktok';
      case 'whatsapp.com':
        return 'hg-whatsapp';
      case 'youtube.com':
      case 'youtu.be':
        return 'hg-youtube';
      case 'snapchat.com':
        return 'hg-snapchat';
      case 'linkedin.com':
        return 'hg-linkedin';
      case 'messenger.com':
        return 'hg-messenger';
      case 'threads.net':
      case 'threads.com':
        return 'hg-thread';
      default:
        return 'hg-web';
    }
  }

  openBasket(event: Event) {
    event.stopPropagation();
    event.preventDefault();

    if (this.media <= Media.sm) {
      this.showBasket = true;
    } else {
      this.messageService.sendComponentMessage(
        CharityBasketPopupComponent,
        { charity: this.charity },
        {
          canBeDismissed: true,
          displayClose: true,
          zIndex: 14
        }
      );
    }
  }

  closeBasket() {
    if (this.basketInstance) {
      this.basketInstance.hasDonated = false;
      this.basketInstance.cdRef.markForCheck();
    }
    this.showBasket = false;
  }
}
