import { Injectable } from '@angular/core';
import { Observable } from 'rxjs';
import { HttpClient } from '@angular/common/http';
import { globalConfiguration } from '@honoregaming/configuration';

@Injectable()
export class SuperReferrerService {
  constructor(private httpClient: HttpClient) {}

  superReferrerRegistration(email: string): Observable<void> {
    return this.httpClient.post<void>(globalConfiguration.apiBaseUrl + 'super-referrer/register', { email });
  }
}
