import { NgModule } from '@angular/core';
import { Routes, RouterModule } from '@angular/router';
import { PointsOfSaleComponent } from './containers/points-of-sale/points-of-sale.component';
import { ContentPageComponent } from './containers/content-page/content-page.component';
import { FaqComponent } from './containers/faq/faq.component';
import { PromotionsComponent } from './containers/promotions/promotions.component';
import { SuperReferrerComponent } from './containers/super-referrer/super-referrer.component';
import { FeaturesGuard } from '@honoregaming/core';
import { LayoutComponent } from './containers/layout/layout.component';
import { CharitiesComponent } from './containers/charities/charities.component';
import { CharityPageComponent } from './containers/charity-page/charity-page.component';

const routes: Routes = [
  {
    path: '',
    component: LayoutComponent,
    children: [
      { path: 'content/:path', component: ContentPageComponent },
      { path: 'points-of-sale', component: PointsOfSaleComponent },
      { path: 'promotions', component: PromotionsComponent },
      { path: 'promotions/content/:path', component: ContentPageComponent, data: { includeAllPromotions: true } },
      { path: 'faq', component: FaqComponent },
      {
        path: 'promotions/super-referrer',
        component: SuperReferrerComponent,
        canActivate: [FeaturesGuard],
        data: { featureName: 'Referral' }
      },
      {
        path: 'charities',
        component: CharitiesComponent,
        canActivate: [FeaturesGuard],
        data: { featureName: 'Charity' }
      },
      {
        path: 'charities/:charityId',
        component: CharityPageComponent,
        canActivate: [FeaturesGuard],
        data: { featureName: 'Charity' }
      }
    ]
  }
];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule]
})
export class HgAboutRoutingModule {}
