import { Component, OnInit, ChangeDetectionStrategy, ChangeDetectorRef, Inject } from '@angular/core';
import { CharityService } from '../../services/charity.service';
import { finalize, switchMap, takeUntil, tap } from 'rxjs/operators';
import { Async, AsyncTrigger, DestroySubject } from '@honoregaming/core';
import { Charity } from '../../models/charity.model';
import { OperatorConfiguration, operatorConfigurationToken } from '@honoregaming/configuration';
import { I18nService } from '@honoregaming/i18n';
import { CharityAmount } from '../../models/charity-amount.model';
import { AuthService } from '@honoregaming/customer-core';

@Component({
  selector: 'hg-charities',
  templateUrl: './charities.component.html',
  styleUrls: ['./charities.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class CharitiesComponent extends DestroySubject implements OnInit {
  charities: Charity[];
  currency: string;

  @AsyncTrigger()
  languageTrigger = this.i18nService.languageChanged$;

  constructor(
    private readonly charityService: CharityService,
    private readonly cdRef: ChangeDetectorRef,
    @Inject(operatorConfigurationToken) private readonly operatorConfiguration: OperatorConfiguration,
    private readonly i18nService: I18nService,
    private readonly authService: AuthService
  ) {
    super();
  }

  ngOnInit() {
    this.currency = this.operatorConfiguration.currency.symbol;

    this.loadCharities();

    this.charityService.charityAmount$.pipe(takeUntil(this.destroy$)).subscribe(ca => this.updateAmount(ca));

    this.authService.me$.pipe(takeUntil(this.destroy$)).subscribe(_ => this.charityService.getCharitiesAmounts());
  }

  @Async()
  loadCharities() {
    this.charityService
      .getCharities()
      .pipe(
        takeUntil(this.destroy$),
        finalize(() => {
          this.cdRef.markForCheck();
        }),
        tap(charities => (this.charities = charities)),
        switchMap(_ => {
          return this.charityService.charityAmounts$;
        })
      )
      .subscribe(charitiesAmounts => {
        this.updateAmounts(charitiesAmounts);
      });
  }

  updateAmount(charityAmount: CharityAmount) {
    if (!charityAmount) {
      return;
    }

    const charity = this.charities.find(c => c.id === charityAmount.id);

    if (charity) {
      this.charityService.updateCharityAmount(charity, charityAmount);
    }
    this.cdRef.markForCheck();
  }

  updateAmounts(charitiesAmounts: CharityAmount[]) {
    this.charities.forEach(charity => {
      const charityAmount = charitiesAmounts?.find(ca => ca.id === charity.id);

      if (charityAmount) {
        this.charityService.updateCharityAmount(charity, charityAmount);
      }
    });
    this.cdRef.markForCheck();
  }
}
